class CsvWriter(Writer):

    def write_row(self, row, delimiter):
        self.out.write(delimiter.join(row))

    def write_rows(self, rows, delimiter):
        self.out.write(len(rows))

    def flush_buffer(self, size, timeout):
        self.out.flush()
